import type { GlobalSettings } from '../../../shared/global-settings-types'
import {
  PLUGIN_APP_THEME_TOKENS,
  type PluginThemeRegistration
} from '../../../shared/plugins/artifacts/plugin-theme-artifact'
import { browserColorProbe, safePluginThemeTokens, type ColorProbe } from './plugin-theme-tokens'

export type DocumentThemePreference = GlobalSettings['theme']

export const THEME_TRANSITION_DISABLED_CLASS = 'theme-transition-disabled'

const DARK_MODE_QUERY = '(prefers-color-scheme: dark)'

type ThemeClassList = {
  add: (...tokens: string[]) => void
  remove: (...tokens: string[]) => void
  toggle: (token: string, force?: boolean) => boolean
}

type ThemeRoot = {
  classList: ThemeClassList
}

type ThemeMediaMatcher = (query: string) => Pick<MediaQueryList, 'matches'>
type ThemeAnimationFrame = (callback: FrameRequestCallback) => number
type ThemeCancelAnimationFrame = (handle: number) => void

type ApplyDocumentThemeOptions = {
  root?: ThemeRoot
  matchMedia?: ThemeMediaMatcher
  requestAnimationFrame?: ThemeAnimationFrame
  cancelAnimationFrame?: ThemeCancelAnimationFrame
  disableTransitions?: boolean
}

let pendingTransitionDisableFrames: number[] = []

function cancelPendingTransitionDisableFrames(cancelFrame: ThemeCancelAnimationFrame): void {
  for (const frameId of pendingTransitionDisableFrames) {
    cancelFrame(frameId)
  }
  pendingTransitionDisableFrames = []
}

function systemPrefersDark(
  matchMedia: ThemeMediaMatcher = window.matchMedia.bind(window)
): boolean {
  return matchMedia(DARK_MODE_QUERY).matches
}

export function resolveDocumentTheme(
  theme: DocumentThemePreference,
  matchMedia?: ThemeMediaMatcher
): boolean {
  if (theme === 'dark') {
    return true
  }
  if (theme === 'light') {
    return false
  }
  return systemPrefersDark(matchMedia)
}

export function applyDocumentTheme(
  theme: DocumentThemePreference,
  options: ApplyDocumentThemeOptions = {}
): void {
  const root = options.root ?? document.documentElement
  const disableTransitions = options.disableTransitions ?? true
  const shouldUseDarkTheme = resolveDocumentTheme(theme, options.matchMedia)

  if (disableTransitions) {
    root.classList.add(THEME_TRANSITION_DISABLED_CLASS)
  }

  root.classList.toggle('dark', shouldUseDarkTheme)
  // Mirror light for symmetric observation; Tailwind still styles only dark.
  root.classList.toggle('light', !shouldUseDarkTheme)

  if (!disableTransitions) {
    return
  }

  const requestFrame = options.requestAnimationFrame ?? window.requestAnimationFrame.bind(window)
  const cancelFrame = options.cancelAnimationFrame ?? window.cancelAnimationFrame.bind(window)
  cancelPendingTransitionDisableFrames(cancelFrame)

  // Wait two frames for root theme recalculation before restoring transitions to avoid staggered fades.
  const firstFrame = requestFrame(() => {
    pendingTransitionDisableFrames = pendingTransitionDisableFrames.filter(
      (id) => id !== firstFrame
    )
    const secondFrame = requestFrame(() => {
      pendingTransitionDisableFrames = pendingTransitionDisableFrames.filter(
        (id) => id !== secondFrame
      )
      root.classList.remove(THEME_TRANSITION_DISABLED_CLASS)
    })
    pendingTransitionDisableFrames.push(secondFrame)
  })
  pendingTransitionDisableFrames.push(firstFrame)
}

type PluginThemeRoot = {
  style: Pick<CSSStyleDeclaration, 'setProperty' | 'removeProperty'>
}

export type CachedPluginAppTheme = {
  id: string
  revision: string
  base: 'light' | 'dark'
  tokens: Record<string, string>
}

/** What an app theme paint needs: a plugin theme, or one Orca synthesizes (Match Terminal). */
export type AppThemePaint = Pick<PluginThemeRegistration, 'base' | 'tokens'> & {
  id: string
  revision: string
}

type PluginThemePaintOptions = {
  root?: PluginThemeRoot
  probe?: ColorProbe
  /** Built-in token values for the current light/dark mode; read from the document by default. */
  builtIns?: () => Record<string, string>
}

const PUBLIC_TOKENS = new Set<string>(PLUGIN_APP_THEME_TOKENS)
const appliedPluginTokens = new WeakMap<object, readonly string[]>()
// Why: plugin themes load after discovery and Match Terminal after settings; repainting from
// this cache before first paint avoids flashing the built-in theme on every launch.
const PLUGIN_THEME_CACHE_KEY = 'orca.pluginAppTheme.lastApplied'

function setPluginTokens(root: PluginThemeRoot, tokens: Record<string, string>): void {
  for (const token of appliedPluginTokens.get(root) ?? []) {
    if (!tokens[token]) {
      root.style.removeProperty(token)
    }
  }
  for (const [token, value] of Object.entries(tokens)) {
    root.style.setProperty(token, value)
  }
  appliedPluginTokens.set(root, Object.keys(tokens))
}

function documentBuiltIns(): Record<string, string> {
  const style = getComputedStyle(document.documentElement)
  return Object.fromEntries(
    PLUGIN_APP_THEME_TOKENS.map((token) => [token, style.getPropertyValue(token).trim()])
  )
}

// Why: menus and dialogs paint a fixed glass tint, which would ignore the theme's --popover
// (a true-black theme got grey dialogs).
const FLOATING_SURFACE_TOKENS = ['--floating-surface', '--dialog-surface'] as const

function withFloatingSurfaces(tokens: Record<string, string>): Record<string, string> {
  const popover = tokens['--popover']
  return popover
    ? { ...tokens, ...Object.fromEntries(FLOATING_SURFACE_TOKENS.map((token) => [token, popover])) }
    : tokens
}

/** Paints tokens that stay readable over this mode's built-ins; returns what was painted. */
function paintPluginTokens(
  { tokens, base }: Pick<CachedPluginAppTheme, 'tokens' | 'base'>,
  options: PluginThemePaintOptions
): Record<string, string> {
  const root = options.root ?? document.documentElement
  // Why clear first: built-ins must be read without the previous theme's overrides.
  setPluginTokens(root, {})
  const safe = safePluginThemeTokens(
    tokens,
    base,
    (options.builtIns ?? documentBuiltIns)(),
    options.probe ?? browserColorProbe
  )
  setPluginTokens(root, withFloatingSurfaces(safe))
  return safe
}

function writeCache(storage: Storage | null, cached: CachedPluginAppTheme | null): void {
  try {
    if (cached) {
      storage?.setItem(PLUGIN_THEME_CACHE_KEY, JSON.stringify(cached))
    } else {
      storage?.removeItem(PLUGIN_THEME_CACHE_KEY)
    }
  } catch {
    // Storage can be full or unavailable; the cache only shortens startup flashes.
  }
}

/** Overlays an app theme's safe tokens and returns them; tokens it no longer sets fall back to
 *  main.css. Call after the document's light/dark mode matches the theme's base. */
export function applyPluginAppTheme(
  theme: AppThemePaint | null,
  options: PluginThemePaintOptions & { storage?: Storage | null } = {}
): Record<string, string> {
  const storage = options.storage === undefined ? globalThis.localStorage : options.storage
  if (!theme) {
    setPluginTokens(options.root ?? document.documentElement, {})
    writeCache(storage, null)
    return {}
  }
  const tokens = paintPluginTokens(theme, options)
  writeCache(storage, { id: theme.id, revision: theme.revision, base: theme.base, tokens })
  return tokens
}

/** The last applied plugin theme, for painting before settings and plugins load. */
export function readCachedPluginAppTheme(
  storage: Storage | null = globalThis.localStorage ?? null
): CachedPluginAppTheme | null {
  try {
    const cached: unknown = JSON.parse(storage?.getItem(PLUGIN_THEME_CACHE_KEY) ?? 'null')
    if (
      typeof cached !== 'object' ||
      cached === null ||
      !('id' in cached) ||
      typeof cached.id !== 'string' ||
      !('revision' in cached) ||
      typeof cached.revision !== 'string' ||
      !('base' in cached) ||
      (cached.base !== 'light' && cached.base !== 'dark') ||
      !('tokens' in cached) ||
      typeof cached.tokens !== 'object' ||
      cached.tokens === null
    ) {
      return null
    }
    const tokens = Object.fromEntries(
      Object.entries(cached.tokens).filter(
        (entry): entry is [string, string] =>
          PUBLIC_TOKENS.has(entry[0]) && typeof entry[1] === 'string'
      )
    )
    return { id: cached.id, revision: cached.revision, base: cached.base, tokens }
  } catch {
    return null
  }
}

/** Repaints a cached theme at startup, re-checked against this mode's built-ins. */
export function applyCachedPluginAppTheme(
  cached: CachedPluginAppTheme,
  options: PluginThemePaintOptions = {}
): void {
  paintPluginTokens(cached, options)
}

import {
  pluginAppThemeCssFallback,
  type PluginThemeCssFallbackRule
} from '../../../shared/plugins/artifacts/plugin-theme-css-fallbacks'

/** sRGB channels 0-255 and alpha 0-1, or null when the value is not a CSS color. */
export type ColorProbe = (value: string) => readonly [number, number, number, number] | null
export type Rgba = readonly [number, number, number, number]

type ContrastRule = {
  surface: string
  text: string
  min: number
  /** What a failure drops, when not both sides: never a shared token this check must not cost. */
  drop?: readonly string[]
  /** A translucent surface is checked as painted over this opaque one. */
  over?: string
  /** Also dropped when the theme omitted the surface, which then follows this token. */
  surfaceSource?: string
}

const MIN_TEXT_CONTRAST = 4.5
// Why 3:1: status hues tint file names, and Orca's own light ignored color is 3.3:1.
const MIN_STATUS_TEXT_CONTRAST = 3
const textPair = (surface: string, text: string): ContrastRule => ({
  surface,
  text,
  min: MIN_TEXT_CONTRAST
})
const GIT_DECORATIONS = [
  'added',
  'modified',
  'deleted',
  'renamed',
  'untracked',
  'copied',
  'ignored'
]

// Why: a theme must not be able to hide text, so every text/surface pair keeps WCAG AA contrast.
const CONTRAST_RULE_DEFINITIONS: readonly ContrastRule[] = [
  textPair('--background', '--foreground'),
  textPair('--background', '--muted-foreground'),
  // Notebook markdown renders directly on the editor surface.
  textPair('--editor-surface', '--foreground'),
  textPair('--editor-surface', '--muted-foreground'),
  textPair('--card', '--card-foreground'),
  textPair('--popover', '--popover-foreground'),
  textPair('--primary', '--primary-foreground'),
  textPair('--secondary', '--secondary-foreground'),
  textPair('--muted', '--muted-foreground'),
  textPair('--accent', '--accent-foreground'),
  textPair('--sidebar', '--sidebar-foreground'),
  textPair('--sidebar-primary', '--sidebar-primary-foreground'),
  textPair('--sidebar-accent', '--sidebar-accent-foreground'),
  textPair('--worktree-sidebar', '--worktree-sidebar-foreground'),
  textPair('--worktree-sidebar-accent', '--worktree-sidebar-accent-foreground'),
  {
    ...textPair('--worktree-sidebar-active', '--worktree-sidebar-foreground'),
    drop: ['--worktree-sidebar-active'],
    over: '--worktree-sidebar'
  },
  { ...textPair('--host-badge', '--host-badge-foreground'), over: '--worktree-sidebar' },
  textPair('--tab-active', '--tab-active-foreground'),
  textPair('--tab-inactive', '--tab-inactive-foreground'),
  // Hovered inactive tabs take the active text color.
  textPair('--tab-inactive', '--tab-active-foreground'),
  {
    ...textPair('--chat-user-message', '--chat-foreground-strong'),
    drop: ['--chat-user-message'],
    over: '--chat-canvas'
  },
  ...['added', 'removed'].flatMap((side): ContrastRule[] => {
    const tint = (kind: string): ContrastRule => ({
      ...textPair(`--diff-${side}-${kind}`, '--foreground'),
      drop: [`--diff-${side}-${kind}`],
      surfaceSource: `--diff-${side}`,
      over: '--editor-surface'
    })
    // Chat diff rows paint the hue-mixed text on the line tint over the chat canvas.
    return [
      tint('background'),
      tint('emphasis'),
      { ...tint('background'), text: `--chat-diff-${side}`, over: '--chat-canvas' }
    ]
  }),
  { ...textPair('--editor-surface', '--text-link'), drop: ['--text-link'] },
  ...GIT_DECORATIONS.map((status): ContrastRule => ({
    surface: '--sidebar',
    text: `--git-decoration-${status}`,
    min: MIN_STATUS_TEXT_CONTRAST,
    drop: [`--git-decoration-${status}`]
  }))
]
const CONTRAST_RULES = CONTRAST_RULE_DEFINITIONS.map((rule) => ({
  ...rule,
  dropped: rule.drop ?? [rule.surface, rule.text]
}))
// Why 2:1, not WCAG's 3:1: Orca's own light ring is 2.6:1; the goal is a ring that never vanishes.
const RINGS: readonly (readonly [string, string])[] = [
  ['--ring', '--background'],
  ['--sidebar-ring', '--sidebar'],
  ['--worktree-sidebar-ring', '--worktree-sidebar'],
  ['--tab-active-indicator', '--tab-active']
]
const MIN_RING_CONTRAST = 2
// Why a floor, not opaque: Orca's own dark borders are 7% white; 0 or near-0 alpha hides them.
const BORDERS = [
  '--border',
  '--input',
  '--sidebar-border',
  '--worktree-sidebar-border',
  '--worktree-sidebar-active-border',
  '--split-divider',
  '--split-divider-hover'
]
const MIN_BORDER_ALPHA = 0.05

function luminance([r, g, b]: Rgba): number {
  const channel = (value: number): number => {
    const c = value / 255
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  }
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

/** WCAG contrast ratio between two opaque colors. */
export function contrastRatio(a: Rgba, b: Rgba): number {
  const first = luminance(a)
  const second = luminance(b)
  return (Math.max(first, second) + 0.05) / (Math.min(first, second) + 0.05)
}

function over([r, g, b, a]: Rgba, [br, bg, bb]: Rgba): Rgba {
  return [r * a + br * (1 - a), g * a + bg * (1 - a), b * a + bb * (1 - a), 1]
}

/** `color-mix(in srgb, a percent%, b)`. */
function mix(a: Rgba, b: Rgba, percent: number): Rgba {
  const p = percent / 100
  const channel = (index: 0 | 1 | 2 | 3): number => a[index] * p + b[index] * (1 - p)
  return [channel(0), channel(1), channel(2), channel(3)]
}

/**
 * The plugin tokens that are safe to paint over the built-in ones for the theme's base.
 * Checks run on the effective set (plugin values, else what main.css derives from them, else
 * built-in), and dropping a token can expose a value that breaks another pair, so checks repeat
 * until nothing changes. Dropped tokens keep their built-in values.
 */
export function safePluginThemeTokens(
  tokens: Readonly<Record<string, string>>,
  base: 'light' | 'dark',
  builtIns: Readonly<Record<string, string>>,
  probe: ColorProbe
): Record<string, string> {
  const accepted = new Map<string, Rgba>()
  for (const [token, value] of Object.entries(tokens)) {
    const color = probe(value)
    if (color && !(BORDERS.includes(token) && color[3] < MIN_BORDER_ALPHA)) {
      accepted.set(token, color)
    }
  }
  const builtInColors = new Map<string, Rgba | null>()
  const derived = (rule: PluginThemeCssFallbackRule): Rgba | null => {
    if ('tint' in rule) {
      const hue = effective(rule.tint)
      return hue ? [hue[0], hue[1], hue[2], (hue[3] * rule.percent) / 100] : null
    }
    if (!('mixForeground' in rule)) {
      return rule.map(effective).find(Boolean) ?? null
    }
    const foreground = effective('--foreground')
    const into = effective(rule.into ?? '--background')
    return foreground && into ? mix(foreground, into, rule.mixForeground) : null
  }
  function effective(token: string): Rgba | null {
    const own = accepted.get(token)
    if (own) {
      return own
    }
    const fallback = pluginAppThemeCssFallback(token, base)
    if (fallback) {
      return derived(fallback)
    }
    if (!builtInColors.has(token)) {
      builtInColors.set(token, builtIns[token] ? probe(builtIns[token]) : null)
    }
    return builtInColors.get(token) ?? null
  }
  const drop = (...pair: string[]): boolean =>
    pair.map((token) => accepted.delete(token)).some(Boolean)

  for (let changed = true; changed;) {
    changed = false
    for (const rule of CONTRAST_RULES) {
      const dropped =
        rule.surfaceSource && tokens[rule.surface] === undefined
          ? [...rule.dropped, rule.surfaceSource]
          : rule.dropped
      // Why skip: a check with nothing of the theme's to drop can't change the result, so a
      // theme that sets none of a check's tokens pays no probes for it.
      if (!dropped.some((token) => accepted.has(token))) {
        continue
      }
      const textColor = effective(rule.text)
      const ownSurface = effective(rule.surface)
      const beneath = rule.over ? effective(rule.over) : null
      const surfaceColor = ownSurface && beneath?.[3] === 1 ? over(ownSurface, beneath) : ownSurface
      if (
        surfaceColor &&
        textColor &&
        (surfaceColor[3] < 1 ||
          textColor[3] < 1 ||
          contrastRatio(surfaceColor, textColor) < rule.min)
      ) {
        changed = drop(...dropped) || changed
      }
    }
    for (const [ring, surface] of RINGS) {
      const ringColor = accepted.get(ring)
      if (!ringColor) {
        continue
      }
      const surfaceColor = effective(surface)
      if (
        surfaceColor &&
        contrastRatio(over(ringColor, surfaceColor), surfaceColor) < MIN_RING_CONTRAST
      ) {
        changed = drop(ring) || changed
      }
    }
  }
  return Object.fromEntries(Object.entries(tokens).filter(([token]) => accepted.has(token)))
}

let probeContext: OffscreenCanvasRenderingContext2D | null | undefined

/** Resolves a color through the browser's own parser by painting one pixel. */
export const browserColorProbe: ColorProbe = (value) => {
  if (typeof CSS === 'undefined' || !CSS.supports('color', value)) {
    return null
  }
  probeContext ??=
    typeof OffscreenCanvas === 'undefined'
      ? null
      : new OffscreenCanvas(1, 1).getContext('2d', { willReadFrequently: true })
  if (!probeContext) {
    return null
  }
  const context = probeContext
  // Why two seeds: fillStyle silently keeps its old value for values it rejects (e.g. `inherit`).
  const paint = (seed: string): number[] => {
    context.clearRect(0, 0, 1, 1)
    context.fillStyle = seed
    context.fillStyle = value
    context.fillRect(0, 0, 1, 1)
    return [...context.getImageData(0, 0, 1, 1).data]
  }
  const first = paint('#000000')
  const second = paint('#ffffff')
  if (first.some((channel, index) => channel !== second[index])) {
    return null
  }
  const [r = 0, g = 0, b = 0, a = 0] = first
  return [r, g, b, a / 255]
}

import type { PluginThemeDerivationRule } from './plugin-theme-artifact'

/** A derivation, or `tint`: `color-mix(in srgb, <tint> <percent>%, transparent)`. */
export type PluginThemeCssFallbackRule =
  | PluginThemeDerivationRule
  | { tint: string; percent: number }

const tint = (token: string, light: number, dark: number) => ({
  light: { tint: token, percent: light },
  dark: { tint: token, percent: dark }
})

/**
 * What main.css paints for a token the theme omits (or the contrast check drops), derived from
 * whatever the theme did paint. Never painted; the contrast check and the token reference read
 * it. Internal chat colors appear so the chat bubble is checked against its real text. Keep in
 * sync with main.css.
 */
const PLUGIN_APP_THEME_CSS_FALLBACKS: Record<
  string,
  PluginThemeCssFallbackRule | Record<'light' | 'dark', PluginThemeCssFallbackRule>
> = {
  '--tab-bar': ['--card'],
  // Why per base: a white light --card can't be lifted, so light recesses the inactive tabs.
  '--tab-active': { light: ['--tab-bar'], dark: { mixForeground: 6, into: '--tab-bar' } },
  '--tab-active-foreground': ['--foreground'],
  '--tab-active-indicator': ['--tab-active-foreground'],
  '--tab-inactive': { light: { mixForeground: 4, into: '--tab-bar' }, dark: ['--tab-bar'] },
  '--tab-inactive-foreground': ['--muted-foreground'],
  '--host-badge': { light: ['--accent'], dark: { tint: '--accent', percent: 80 } },
  '--host-badge-foreground': ['--muted-foreground'],
  '--diff-added': ['--git-decoration-added'],
  '--diff-removed': ['--git-decoration-deleted'],
  '--diff-added-background': tint('--diff-added', 13, 16),
  '--diff-added-emphasis': tint('--diff-added', 15, 20),
  '--diff-added-gutter': tint('--diff-added', 26, 30),
  '--diff-removed-background': tint('--diff-removed', 11, 18),
  '--diff-removed-emphasis': tint('--diff-removed', 15, 20),
  '--diff-removed-gutter': tint('--diff-removed', 22, 32),
  '--chat-diff-added': { mixForeground: 30, into: '--diff-added' },
  '--chat-diff-removed': { mixForeground: 30, into: '--diff-removed' },
  // At the default chat contrast setting.
  '--chat-canvas': { light: ['--background'], dark: { mixForeground: 5 } },
  '--chat-foreground-strong': {
    light: { mixForeground: 92, into: '--chat-canvas' },
    dark: { mixForeground: 90, into: '--chat-canvas' }
  }
}

export function pluginAppThemeCssFallback(
  token: string,
  base: 'light' | 'dark'
): PluginThemeCssFallbackRule | undefined {
  const rule = PLUGIN_APP_THEME_CSS_FALLBACKS[token]
  return rule && 'light' in rule ? rule[base] : rule
}

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { contrastRatio, type Rgba } from '../lib/plugin-theme-tokens'

const css = readFileSync(new URL('./main.css', import.meta.url), 'utf8').replace(
  /\/\*[\s\S]*?\*\//g,
  ''
)

/** Last-wins hex tokens from every top-level block whose selector list starts with `selector`. */
function themeTokens(selector: ':root' | '.dark'): Map<string, Rgba> {
  const tokens = new Map<string, Rgba>()
  for (const [, selectors, body] of css.matchAll(/(?:^|\n)([^{}\n][^{}]*)\{([^{}]*)\}/g)) {
    if (selectors.trim().split(/\s*,\s*/)[0] !== selector) {
      continue
    }
    for (const [, name, hex] of body.matchAll(/(--[\w-]+):\s*#([0-9a-f]{3}|[0-9a-f]{6});/gi)) {
      const digits = hex.length === 3 ? hex.replace(/./g, '$&$&') : hex
      const [r, g, b] = [0, 2, 4].map((i) => Number.parseInt(digits.slice(i, i + 2), 16))
      tokens.set(name, [r, g, b, 1])
    }
  }
  return tokens
}

function tint(color: Rgba, amount: number, surface: Rgba): Rgba {
  const [r, g, b] = [0, 1, 2].map((i) => color[i] * amount + surface[i] * (1 - amount))
  return [r, g, b, 1]
}

const successTint = Number(
  css.match(/--status-success-background: color-mix\(in srgb, var\(--status-success\) (\d+)%/)?.[1]
)

describe.each([':root', '.dark'] as const)('built-in %s token pairs', (selector) => {
  const tokens = themeTokens(selector)
  const token = (name: string): Rgba => {
    const value = tokens.get(name)
    if (!value) {
      throw new Error(`${name} is not a hex color in ${selector}`)
    }
    return value
  }

  it.each([
    ['--destructive-foreground', '--destructive'],
    ['--muted-foreground', '--background'],
    ['--muted-foreground', '--muted'],
    ['--muted-foreground', '--accent'],
    ['--muted-foreground', '--card']
  ])('%s on %s meets WCAG AA', (text, surface) => {
    expect(contrastRatio(token(text), token(surface))).toBeGreaterThanOrEqual(4.5)
  })

  it.each(['--background', '--muted'])('success text on its tint over %s meets WCAG AA', (name) => {
    const surface = tint(token('--status-success'), successTint / 100, token(name))
    expect(contrastRatio(token('--status-success'), surface)).toBeGreaterThanOrEqual(4.5)
  })
})

