const { isDeepStrictEqual, inspect } = require('node:util')
const clean = (v) => JSON.parse(JSON.stringify(v ?? null))
const tests = []; let prefix = []
const describe = (name, fn) => { prefix.push(name); fn(); prefix.pop() }
describe.each = (rows) => (name, fn) => rows.forEach((r) => describe(name.replace('%s', r), () => fn(r)))
const it = (name, fn) => tests.push([[...prefix, name].join(' > '), fn])
it.each = (rows) => (name, fn) => rows.forEach((r) => it(name, () => (Array.isArray(r) ? fn(...r) : fn(r))))
function matchers(actual, neg) {
  const check = (ok, msg) => { if (ok === neg) throw new Error((neg ? 'NOT ' : '') + msg) }
  return {
    toEqual: (e) => check(isDeepStrictEqual(clean(actual), clean(e)), `${inspect(actual)} toEqual ${inspect(e)}`),
    toStrictEqual: (e) => check(isDeepStrictEqual(actual, e), `${inspect(actual)} toStrictEqual ${inspect(e)}`),
    toBe: (e) => check(Object.is(actual, e), `${inspect(actual)} toBe ${inspect(e)}`),
    toBeNull: () => check(actual === null, `${inspect(actual)} toBeNull`),
    toBeUndefined: () => check(actual === undefined, `${inspect(actual)} toBeUndefined`),
    toBeTruthy: () => check(!!actual, `${inspect(actual)} toBeTruthy`),
    toContain: (e) => check(actual.includes(e), `${inspect(actual)} toContain ${inspect(e)}`),
    toHaveProperty: (k, ...v) => check(k in Object(actual) && (v.length === 0 || isDeepStrictEqual(actual[k], v[0])), `toHaveProperty ${k}`),
    toBeGreaterThanOrEqual: (e) => check(actual >= e, `${actual} >= ${e}`),
    toThrow: (e) => { let threw = false; try { actual() } catch { threw = true } check(threw, 'toThrow') }
  }
}
const expect = (a) => Object.assign(matchers(a, false), { not: matchers(a, true) })
process.on('beforeExit', () => {
  if (globalThis.__ran) return; globalThis.__ran = true
  let fail = 0
  for (const [name, fn] of tests) { try { fn(); console.log('ok   ', name) } catch (e) { fail++; console.log('FAIL ', name, '\n     ', e.message) } }
  console.log(`${tests.length - fail}/${tests.length} passed`); process.exitCode = fail ? 1 : 0
})
module.exports = { describe, it, expect, vi: {} }
EOF
